SELECT COUNT(*)
FROM study_group_members
WHERE study_group_id = #{studyGroupId}
  AND status = #{status}


SELECT COUNT(*)
FROM study_group_members M
INNER JOIN study_groups SG ON SG.id = M.study_group_id
WHERE SG.owner_id = #{ownerId}
  AND M.status = #{status}
  AND M.notification_read_yn = #{notificationReadYn}


SELECT COUNT(*)
FROM study_group_members M
WHERE M.user_id = #{userId}
  AND M.status IN


#{status}


  AND M.notification_read_yn = #{notificationReadYn}

SELECT M.id, M.status, M.notification_read_yn, M.created_at, M.updated_at, SG.id AS `studyGroup.id`, SG.title AS `studyGroup.title`, U.id AS `studyGroup.owner.id`, U.nickname AS `studyGroup.owner.nickname`, M.user_id AS `user.id` FROM study_group_members M INNER JOIN study_groups SG ON SG.id = M.study_group_id INNER JOIN users U ON U.id = SG.owner_id WHERE M.user_id = #{userId} AND M.status IN
#{status}
ORDER BY M.updated_at DESC

SELECT M.id, M.status, M.notification_read_yn, M.created_at, M.updated_at, M.study_group_id AS `studyGroup.id`, M.user_id AS `user.id` FROM study_group_members M WHERE M.user_id = #{userId} AND M.status IN
#{status}
AND M.notification_read_yn = #{notificationReadYn}
